UPDATE service_item
SET status         = 'REVIEWING',
    submission_no  = submission_no + 1,
    submitted_at   = #{now},
    version        = version + 1,
    updated_at     = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND status IN ('DRAFT', 'REJECTED', 'OFFLINE')

UPDATE service_item
SET status     = 'OFFLINE',
    version    = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND status = 'ACTIVE'

UPDATE service_item
SET status     = 'ACTIVE',
    version    = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND status = 'REVIEWING'

UPDATE service_item
SET status     = 'REJECTED',
    version    = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND status = 'REVIEWING'

UPDATE service_item
SET status     = 'OFFLINE',
    version    = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}
  AND status = 'ACTIVE'

